public static int maxRegions(int N) {
    if (N <= 0) {
        // If there are no triangles, the plane remains undivided, so there is exactly one region.
        return 1;
    }
    // The formula 4N^2 - 6N + 4 fits the known sequence for maximum regions created by N triangles.
    // To avoid integer overflow, check that N is within the safe range for int computation.
    // Integer.MAX_VALUE ≈ 2.14×10^9, so 4*N^2 must not exceed this.
    // Solve 4*N^2 <= Integer.MAX_VALUE => N <= floor(sqrt(Integer.MAX_VALUE/4)) ≈ 23170.
    if (N > 23170) {
        throw new IllegalArgumentException("N is too large to compute accurately with int precision");
    }
    long result = 4L * N * N - 6L * N + 4L;
    return (int) result;
}

