private int dfs(int node, java.util.List<Integer>[] adj, boolean[] hasApple, boolean[] visited) {
    visited[node] = true;
    int time = 0;
    for (int nei : adj[node]) {
        if (!visited[nei]) {
            int childTime = dfs(nei, adj, hasApple, visited);
            if (childTime > 0 || hasApple[nei]) {
                time += childTime + 2;
            }
        }
    }
    return time;
}

public String sortString(String s) {
    if (s == null) {
        return null;
    }
    int length = s.length();
    if (length == 0) {
        return "";
    }

    java.util.TreeMap<Character, Integer> counts = new java.util.TreeMap<>();
    for (int i = 0; i < length; ++i) {
        char c = s.charAt(i);
        Integer cnt = counts.get(c);
        counts.put(c, (cnt == null) ? 1 : cnt + 1);
    }

    StringBuilder result = new StringBuilder(length);

    while (!counts.isEmpty()) {
        // Ascending pass
        Character last = counts.firstKey();
        result.append(last);
        int cntLast = counts.get(last);
        if (cntLast == 1) {
            counts.remove(last);
        } else {
            counts.put(last, cntLast - 1);
        }

        while (true) {
            Character next = counts.higherKey(last);
            if (next == null) {
                break;
            }
            result.append(next);
            int cntNext = counts.get(next);
            if (cntNext == 1) {
                counts.remove(next);
            } else {
                counts.put(next, cntNext - 1);
            }
            last = next;
        }

        if (counts.isEmpty()) {
            break;
        }

        // Descending pass
        Character lastDesc = counts.lastKey();
        result.append(lastDesc);
        int cntLastDesc = counts.get(lastDesc);
        if (cntLastDesc == 1) {
            counts.remove(lastDesc);
        } else {
            counts.put(lastDesc, cntLastDesc - 1);
        }

        while (true) {
            Character prev = counts.lowerKey(lastDesc);
            if (prev == null) {
                break;
            }
            result.append(prev);
            int cntPrev = counts.get(prev);
            if (cntPrev == 1) {
                counts.remove(prev);
            } else {
                counts.put(prev, cntPrev - 1);
            }
            lastDesc = prev;
        }
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) {
        return false;
    }

    int totalSum = 0;
    for (int v : nums) {
        totalSum += v;
    }

    int maxK = n / 2;
    // dp[k][s] == true if we can pick k elements that sum to s
    boolean[][] dp = new boolean[maxK + 1][totalSum + 1];
    dp[0][0] = true;

    for (int num : nums) {
        // iterate k in descending order to avoid using the same element more than once
        for (int k = maxK - 1; k >= 0; k--) {
            for (int s = 0; s <= totalSum - num; s++) {
                if (dp[k][s]) {
                    dp[k + 1][s + num] = true;
                }
            }
        }
    }

    for (int k = 1; k <= maxK; k++) {
        long product = (long) totalSum * k;
        if (product % n != 0) {
            continue;
        }
        int target = (int) (product / n);
        if (dp[k][target]) {
            return true;
        }
    }

    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        return cost[0];
    }
    int prev2 = cost[0];
    int prev1 = cost[1];
    for (int i = 2; i < n; i++) {
        int current = cost[i] + Math.min(prev1, prev2);
        prev2 = prev1;
        prev1 = current;
    }
    return Math.min(prev1, prev2);
}

public int uniqueMorseRepresentations(String[] words) {
    if (words == null) {
        // If the input array itself is null, we consider there are no transformations.
        return 0;
    }
    // Morse code representation for each letter of the English alphabet
    String[] morse = {
        ".-","-...","-.-.","-..",".","..-.","--.","....","..",
        ".---","-.-",".-..","--","-.", "---",".--.","--.-",".-.",
        "...","-","..-","...-",".--","-..-","-.--","--.."
    };
    java.util.Set<String> uniqueSet = new java.util.HashSet<>();
    for (String word : words) {
        if (word == null) {
            // Skip null entries to avoid NullPointerException
            continue;
        }
        StringBuilder transformed = new StringBuilder();
        for (char c : word.toCharArray()) {
            // Support both lowercase and uppercase letters
            if (c >= 'a' && c <= 'z') {
                transformed.append(morse[c - 'a']);
            } else if (c >= 'A' && c <= 'Z') {
                transformed.append(morse[c - 'A']);
            } else {
                // For any non-alphabetic character, we simply ignore it.
                // Alternatively, we could throw an exception if that behavior is preferred.
            }
        }
        uniqueSet.add(transformed.toString());
    }
    return uniqueSet.size();
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0 || s.length() < k) {
        return false;
    }
    int required = 1 << k;
    // If there are not enough substrings to cover all possible codes
    if (required > s.length() - k + 1) {
        return false;
    }
    boolean[] seen = new boolean[required];
    int mask = required - 1;
    int code = 0;
    // Build the first code of length k
    for (int i = 0; i < k; i++) {
        code = (code << 1) | (s.charAt(i) - '0');
    }
    seen[code] = true;
    int distinct = 1;

    for (int i = k; i < s.length(); i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[code]) {
            seen[code] = true;
            distinct++;
            if (distinct == required) {
                return true;
            }
        }
    }
    return distinct == required;
}

