public int minInsertions(String s) {
    if (s == null) {
        return 0;
    }
    int balance = 0;   // number of unmatched '(' encountered so far
    int insertions = 0; // total number of insertions needed

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            if (balance == 0) {
                // need an '(' before this ')'
                insertions++;
            } else {
                balance--; // match this ')' with a previous '('
            }
        } else {
            // In case of unexpected characters, ignore them
            // As per problem statement, s only contains '(' or ')'
        }
    }

    // Any remaining unmatched '(' need a ')' after the string
    insertions += balance;
    return insertions;
}

public int minOperations(int n) {
    // Validate input: non-positive n yields no operations
    if (n <= 0) {
        return 0;
    }
    try {
        // t = floor((n - 1) / 2)
        int t = (n - 1) / 2;
        long part1 = (long) (t + 1);
        long part2 = (long) (n - t - 1);
        long ops = part1 * part2;
        // Clamp result to int range
        if (ops > Integer.MAX_VALUE) {
            throw new ArithmeticException("Result exceeds maximum int value");
        }
        return (int) ops;
    } catch (Exception e) {
        // In case of unexpected errors, return -1 or rethrow
        return -1;
    }
}

