            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    // Validate input
    if (n <= 0 || k <= 0) {
        return -1;
    }

    java.util.ArrayList<Integer> smallFactors = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> largeFactors = new java.util.ArrayList<>();

    int limit = (int) Math.sqrt(n);
    for (int i = 1; i <= limit; i++) {
        if (n % i == 0) {
            smallFactors.add(i);
            int other = n / i;
            if (other != i) {
                largeFactors.add(other);
            }
        }
    }

    int totalFactors = smallFactors.size() + largeFactors.size();
    if (k > totalFactors) {
        return -1;
    }

    // kth factor in ascending order
    if (k <= smallFactors.size()) {
        return smallFactors.get(k - 1);
    } else {
        int indexInLarge = k - smallFactors.size() - 1;
        // largeFactors were added in ascending order of i, so they are descending when viewed ascending
        return largeFactors.get(largeFactors.size() - 1 - indexInLarge);
    }
}

