        int len = sb.length();
        if (len > 0 && Math.abs(c - sb.charAt(len - 1)) == 32) {
            sb.deleteCharAt(len - 1);  // remove the adjacent pair
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    final int n = s.length();
    final int[] maxCount = {0};

    class SplitHelper {
        void dfs(int index, java.util.Set<String> used) {
            if (index == n) {
                if (used.size() > maxCount[0]) {
                    maxCount[0] = used.size();
                }
                return;
            }
            for (int i = index + 1; i <= n; i++) {
                String sub = s.substring(index, i);
                if (!used.contains(sub)) {
                    used.add(sub);
                    dfs(i, used);
                    used.remove(sub);
                }
            }
        }
    }

    new SplitHelper().dfs(0, new java.util.HashSet<>());
    return maxCount[0];
}

public int minOperations(String[] logs) {
    if (logs == null || logs.length == 0) {
        return 0;
    }
    int depth = 0;
    for (String log : logs) {
        if (log == null) {
            continue;
        }
        // Normalize the log by trimming whitespace
        log = log.trim();
        if ("../".equals(log)) {
            if (depth > 0) {
                depth--;
            }
        } else if ("./".equals(log)) {
            // stay in the current folder, no action needed
        } else if (log.endsWith("/")) {
            // enter a subfolder
            depth++;
        }
        // Any other format is considered invalid but ignored
    }
    return depth;
}

public String getSmallestString(int n, int k) {
    // Validate input: minimum value is all 'a's (value 1 each)
    if (n <= 0 || k < n || k > 26 * n) {
        // Return empty string for invalid requests
        return "";
    }
    char[] result = new char[n];
    // Start with all 'a'
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    int diff = k - n; // extra value needed beyond all 'a's
    // Distribute the extra value starting from the end (rightmost)
    for (int i = n - 1; i >= 0 && diff > 0; i--) {
        int add = Math.min(25, diff); // can increase by at most 25 ('z' - 'a')
        result[i] = (char) (result[i] + add);
        diff -= add;
    }
    return new String(result);
}

