public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty");
    }
    int[] bitCount = new int[32];
    for (int num : nums) {
        for (int i = 0; i < 32; i++) {
            bitCount[i] += (num >> i) & 1;
        }
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        if ((bitCount[i] % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static java.util.List<Integer> findSteppingNumbers(int low, int high) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (low > high) {
        return result;
    }
    java.util.Queue<Long> queue = new java.util.LinkedList<>();
    for (int i = 0; i <= 9; i++) {
        queue.add((long) i);
    }
    while (!queue.isEmpty()) {
        long current = queue.poll();
        if (current > high) {
            continue;
        }
        if (current >= low) {
            result.add((int) current);
        }
        int lastDigit = (int) (current % 10);
        int nextDigit1 = lastDigit + 1;
        int nextDigit2 = lastDigit - 1;

        if (nextDigit1 <= 9) {
            long next = current * 10 + nextDigit1;
            if (next <= high) {
                queue.add(next);
            }
        }
        if (nextDigit2 >= 0) {
            long next = current * 10 + nextDigit2;
            if (next <= high) {
                queue.add(next);
            }
        }
    }
    java.util.Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0; // No positive numbers to count
    }
    long count = 0;
    long factor = 1;
    while (factor <= n) {
        long lower = n % factor;
        long current = (n / factor) % 10;
        long higher = n / (factor * 10);

        count += higher * factor;
        if (current == 1) {
            count += lower + 1;
        } else if (current > 1) {
            count += factor;
        }

        factor *= 10;
    }
    return (int) count;
}

