public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return 0;
    }
    // Determine the number of columns; ensure the first row is not null
    int n = 0;
    for (int[] row : mat) {
        if (row != null) {
            n = row.length;
            break;
        }
    }
    if (n == 0) {
        return 0;
    }

    int m = mat.length;
    int[][] hor = new int[m][n];
    int[][] ver = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] anti = new int[m][n];
    int max = 0;

    for (int i = 0; i < m; i++) {
        if (mat[i] == null) {
            continue; // Treat rows that are null as all zeros
        }
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                hor[i][j] = (j > 0) ? hor[i][j - 1] + 1 : 1;
                ver[i][j] = (i > 0) ? ver[i - 1][j] + 1 : 1;
                diag[i][j] = (i > 0 && j > 0) ? diag[i - 1][j - 1] + 1 : 1;
                anti[i][j] = (i > 0 && j < n - 1) ? anti[i - 1][j + 1] + 1 : 1;
                int currentMax = Math.max(
                        Math.max(hor[i][j], ver[i][j]),
                        Math.max(diag[i][j], anti[i][j])
                );
                if (currentMax > max) {
                    max = currentMax;
                }
            } else {
                hor[i][j] = 0;
                ver[i][j] = 0;
                diag[i][j] = 0;
                anti[i][j] = 0;
            }
        }
    }
    return max;
}

public static String addThousandSeparator(int n) {
    boolean negative = n < 0;
    long value = Math.abs((long) n);
    StringBuilder sb = new StringBuilder();
    int count = 0;
    do {
        sb.append((char) ('0' + (int)(value % 10)));
        value /= 10;
        count++;
        if (value > 0 && count % 3 == 0) {
            sb.append('.');
        }
    } while (value > 0);
    if (negative) {
        sb.append('-');
    }
    return sb.reverse().toString();
}

public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) {
        return 1;
    }
    int n = A.length;
    java.util.Arrays.sort(A);
    boolean[] used = new boolean[n];
    int[] count = new int[1];
    backtrack(A, used, 0, -1, count);
    return count[0];
}

private static void backtrack(int[] A, boolean[] used, int depth, int last, int[] count) {
    int n = A.length;
    if (depth == n) {
        count[0]++;
        return;
    }
    int prev = -1;
    for (int i = 0; i < n; i++) {
        if (used[i]) continue;
        if (prev != -1 && A[i] == prev) continue;
        if (depth > 0 && !isPerfectSquare(A[i] + last)) continue;
        used[i] = true;
        backtrack(A, used, depth + 1, A[i], count);
        used[i] = false;
        prev = A[i];
    }
}

private static boolean isPerfectSquare(int sum) {
    int sqrt = (int) Math.sqrt(sum);
    return sqrt * sqrt == sum;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int n = heights.length;
    if (n == 0) {
        return 0;
    }
    java.util.ArrayDeque<Integer> stack = new java.util.ArrayDeque<>();
    long maxArea = 0L;
    for (int i = 0; i <= n; i++) {
        long currentHeight = (i < n) ? heights[i] : 0L;
        if (currentHeight < 0) {
            throw new IllegalArgumentException("Bar heights must be non-negative");
        }
        while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    return (int) Math.min(maxArea, Integer.MAX_VALUE);
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int total = m * n;
    int[] result = new int[total];
    int index = 0;

    for (int d = 0; d <= m + n - 2; d++) {
        int row = d < m ? d : m - 1;
        int col = d < m ? 0 : d - (m - 1);

        if ((d & 1) == 0) { // even diagonal, move up-right
            while (row >= 0 && col < n) {
                result[index++] = mat[row][col];
                row--;
                col++;
            }
        } else { // odd diagonal, move down-left
            while (row < m && col >= 0) {
                result[index++] = mat[row][col];
                row++;
                col--;
            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }

    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Find the first index 'i' from the end where digits[i] < digits[i+1]
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        // Digits are in non-increasing order; no larger permutation
        return -1;
    }

    // Find the first index 'j' from the end where digits[j] > digits[i]
    int j = len - 1;
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }

    // Swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the suffix starting at i+1
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }

    // Convert back to integer, checking for overflow
    long result = 0;
    for (char c : digits) {
        result = result * 10 + (c - '0');
        if (result > Integer.MAX_VALUE) {
            return -1; // overflow in int range
        }
    }

    return (int) result;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> res = new ArrayList<>();
    if (n <= 0) return res;

    // mapping of digits to their mirror counterparts
    int[] firstDigits = {0, 1, 6, 8, 9};
    int[] mirrorDigits = {0, 1, 9, 8, 6};

    // helper to generate combinations for the first half
    int halfLen = n / 2;
    if (halfLen == 0) {
        // n == 1
        res.add("0");
        res.add("1");
        res.add("8");
        return res;
    }

    // Build all possible first halves
    List<String> firstHalfList = new ArrayList<>();
    // start with first digit (cannot be 0 if n > 1)
    for (int i = 0; i < firstDigits.length; i++) {
        if (halfLen > 0 && firstDigits[i] == 0) continue;
        char firstChar = (char) ('0' + firstDigits[i]);
        firstHalfList.add(String.valueOf(firstChar));
    }

    // extend to full length of first half (halfLen)
    while (firstHalfList.size() > 0 && firstHalfList.get(0).length() < halfLen) {
        List<String> newList = new ArrayList<>();
        for (String prefix : firstHalfList) {
            for (int d : firstDigits) {
                newList.add(prefix + (char) ('0' + d));
            }
        }
        firstHalfList = newList;
    }

    // construct full numbers
    for (String firstHalf : firstHalfList) {
        if (n % 2 == 0) {
            // even length: mirror entire first half
            StringBuilder sb = new StringBuilder(firstHalf);
            for (int i = firstHalf.length() - 1; i >= 0; i--) {
                char c = firstHalf.charAt(i);
                int idx = c - '0';
                sb.append(mirrorDigits[idx]);
            }
            res.add(sb.toString());
        } else {
            // odd length: iterate over middle digits 0,1,8
            for (char mid : new char[]{'0', '1', '8'}) {
                StringBuilder sb = new StringBuilder(firstHalf);
                sb.append(mid);
                for (int i = firstHalf.length() - 1; i >= 0; i--) {
                    char c = firstHalf.charAt(i);
                    int idx = c - '0';
                    sb.append(mirrorDigits[idx]);
                }
                res.add(sb.toString());
            }
        }
    }

    return res;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    // Check for duplicate points
    int x0 = points[0][0], y0 = points[0][1];
    int x1 = points[1][0], y1 = points[1][1];
    int x2 = points[2][0], y2 = points[2][1];
    if (x0 == x1 && y0 == y1) return false;
    if (x0 == x2 && y0 == y2) return false;
    if (x1 == x2 && y1 == y2) return false;
    // Use cross product to check collinearity
    long cross = (long)(x1 - x0) * (y2 - y0) - (long)(y1 - y0) * (x2 - x0);
    return cross != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int max = 1;
    int current = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            current++;
        } else {
            if (current > max) {
                max = current;
            }
            current = 1;
        }
    }
    if (current > max) {
        max = current;
    }
    return max;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result; // Empty list for non-positive input
    }
    int current = 1;
    for (int i = 0; i < n; i++) {
        result.add(current);
        if (current * 10 <= n) {
            current *= 10; // Go deeper in the tree
        } else {
            // If we cannot go deeper, move to the next sibling or ascend
            while (current % 10 == 9 || current + 1 > n) {
                current /= 10;
            }
            current++;
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int num : nums) {
        freq.put(num, freq.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return n == 0 ? 0 : -1; // negative input not allowed
    }
    // Legendre's Three Square Theorem
    int m = n;
    while (m % 4 == 0) {
        m /= 4;
    }
    if (m % 8 == 7) {
        return 4;
    }
    if (isPerfectSquare(n)) {
        return 1;
    }
    if (canBeSumOfTwoSquares(n)) {
        return 2;
    }
    return 3;
}

private static boolean isPerfectSquare(int x) {
    int r = (int) Math.sqrt(x);
    return r * r == x;
}

private static boolean canBeSumOfTwoSquares(int x) {
    int limit = (int) Math.sqrt(x);
    for (int i = 1; i <= limit; i++) {
        int remaining = x - i * i;
        if (isPerfectSquare(remaining)) {
            return true;
        }
    }
    return false;
}

public static String reverseWords(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c != ' ') {
            word.append(c);
        } else {
            // End of a word
            result.append(word.reverse());
            word.setLength(0); // reset word
            result.append(c);  // add the space
        }
    }
    // Append the last word (if any)
    result.append(word.reverse());
    return result.toString();
}
